<div class="page-actions"><h2>Sales Order</h2><?php if (in_array($currentUser['role'] ?? '', ['Admin','Sales'], true)): ?><a class="btn btn-primary" href="?page=sales&action=create">+ Tambah SO</a><?php endif; ?></div>
<div class="card filter-card"><form method="get" class="filter-grid"><input type="hidden" name="page" value="sales"><input name="search" value="<?=e($filters['search'])?>" placeholder="Cari nomor SO atau customer"><select name="status"><option value="">Semua status</option><?php foreach(['Draft','PendingApproval','Approved','Fulfilled','Cancelled'] as $status):?><option value="<?=e($status)?>" <?=$filters['status']===$status?'selected':''?>><?=e($status)?></option><?php endforeach;?></select><select name="sort"><option value="date_desc" <?=$filters['sort']==='date_desc'?'selected':''?>>Tanggal terbaru</option><option value="date_asc" <?=$filters['sort']==='date_asc'?'selected':''?>>Tanggal terlama</option></select><button class="btn btn-primary">Filter</button><a class="btn" href="?page=sales">Reset</a></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Nomor SO</th><th>Tanggal</th><th>Customer</th><th>Gudang</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($result['items'] as $order): ?><tr><td><a class="link" href="?page=sales&action=view&id=<?= $order['id'] ?>"><?= e($order['so_number']) ?></a></td><td><?= e($order['so_date']) ?></td><td><?= e($order['customer_name']) ?></td><td><?= e($order['warehouse_name']) ?></td><td>Rp <?= number_format((float) $order['total_amount'], 0, ',', '.') ?></td><td><span class="badge"><?= e($order['status']) ?></span></td><td><?php $role=$currentUser['role']??''; $next=($role==='Sales'&&$order['status']==='Draft')?'PendingApproval':(($role==='Admin'&&$order['status']==='PendingApproval')?'Approved':(($role==='WarehouseStaff'&&$order['status']==='Approved')?'Fulfilled':null)); ?><?php if ($next): ?><form class="inline-form" method="post" action="?page=sales&action=status&id=<?= $order['id'] ?>"><?= $csrfField ?><input type="hidden" name="status" value="<?= $next ?>"><button class="btn btn-sm"><?= $next==='Fulfilled'?'Goods Issue':$next ?></button></form><?php endif; ?><?php if($role==='Admin'&&$order['status']==='PendingApproval'): ?><form class="inline-form" method="post" action="?page=sales&action=status&id=<?= $order['id'] ?>"><?= $csrfField ?><input type="hidden" name="status" value="Cancelled"><button class="btn btn-sm danger-btn">Tolak</button></form><?php endif; ?><?php if (!$next && !($role==='Admin'&&$order['status']==='PendingApproval')): ?>-<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$result['items']): ?><tr><td colspan="7" class="empty">Tidak ada Sales Order yang cocok dengan filter.</td></tr><?php endif; ?></tbody></table></div><?= paginationLinks($result, ['page'=>'sales','search'=>$filters['search'],'status'=>$filters['status'],'sort'=>$filters['sort']]) ?></div>
